import { Component, computed, input } from '@angular/core';
import { FigPipe } from '../../core/locale';
import { STATUSES } from '../summary/summary';

// The sheet's counters, shown at all times: each repeats a figure shown elsewhere — the status counts those of the
// summary, the two totals the sheet's totals, the signed-in user's own figures those of their person's row,
// and their crew total those of the crews their person leads.
@Component({
  selector: 'app-header',
  imports: [FigPipe],
  template: `
    <header aria-label="Sheet counters">
      <dl>
        <dt>People</dt>
        <dd data-testid="header-people-count">{{ peopleCount() | fig }}</dd>
        @for (s of byStatus(); track s.status) {
          <dt>{{ s.status }}</dt>
          <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count | fig }}</dd>
        }
        <dt>Due</dt>
        <dd data-testid="header-due-total">{{ dueTotal() | fig }}</dd>
        <dt>Overdue</dt>
        <dd data-testid="header-overdue-total">{{ overdueTotal() | fig }}</dd>
        <dt>My due</dt>
        <dd data-testid="my-due-total">{{ myDueTotal() | fig }}</dd>
        <dt>My overdue</dt>
        <dd data-testid="my-overdue-total">{{ myOverdueTotal() | fig }}</dd>
        <dt>My crew due</dt>
        <dd data-testid="my-crew-due-total">{{ myCrewDueTotal() | fig }}</dd>
        <dt>My reviews</dt>
        <dd data-testid="my-reviews-count">{{ myReviewsCount() | fig }}</dd>
      </dl>
    </header>
  `,
})
export class Header {
  // Everyone on the sheet, retired people included.
  readonly peopleCount = input(0);
  // The status of every claim on the sheet, as the summary counts them.
  readonly statuses = input<readonly string[]>([]);
  readonly dueTotal = input('');
  readonly overdueTotal = input('');
  // The signed-in user's own figures, as on the row of the person with their name or alias; blank with no such person.
  readonly myDueTotal = input('');
  readonly myOverdueTotal = input('');
  // The due-totals of the crews that person leads, added up; blank when they lead none.
  readonly myCrewDueTotal = input('');
  // The REVIEW claims assigned to the signed-in user.
  readonly myReviewsCount = input(0);

  protected readonly byStatus = computed(() =>
    STATUSES.map((status) => ({ status, count: this.statuses().filter((s) => s === status).length })),
  );
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.Audit;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people each user watches on a sheet, and the notices a watched person's settled claims send them. */
@Service
public class WatchService {

    private final WatchRepository watches;
    private final PersonRepository people;
    private final Audit audit;

    public WatchService(WatchRepository watches, PersonRepository people, Audit audit) {
        this.watches = watches;
        this.people = people;
        this.audit = audit;
    }

    /** The ids of the people the user watches on the sheet. */
    @Transactional(readOnly = true)
    public List<Long> watched(String sheetId, String user) {
        return watches.findBySheetIdAndUserNameOrderByIdAsc(sheetId, user).stream().map(Watch::getPersonId).toList();
    }

    /** Starts (on) or stops the user watching the person; a person already in that state is left as they are. */
    @Transactional
    public boolean watch(String user, String sheetId, Long personId, boolean on) {
        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
        if (on && existing.isEmpty()) {
            try {
                watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
            } catch (DataIntegrityViolationException e) {
                return true;
            }
            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
        } else if (!on && existing.isPresent()) {
            watches.delete(existing.get());
            watches.flush();
            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
        }
        return on;
    }

    /**
     * Records one notice per user watching the person, in the order they started watching, that the claim with the
     * number was settled; called after the claim's own record and before the rollup's.
     */
    public void notifyWatchers(String by, String sheetId, Person person, String number) {
        for (Watch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + by + " user=" + w.getUserName() + " person="
                    + person.getName() + " number=" + number);
        }
    }
}
