imports: [FigPipe, Claims, Consolidated, Dashboard, Header, Periods, PersonPlans, Summary],
template: `
  <app-header
    [peopleCount]="people().length"
    [statuses]="claimStatuses()"
    [dueTotal]="dueTotal()"
    [overdueTotal]="overdueTotal()"
    [myDueTotal]="myFigures()?.dueTotal ?? ''"
    [myOverdueTotal]="myFigures()?.overdueTotal ?? ''"
    [myCrewDueTotal]="myCrewDueTotal()"
    [myReviewsCount]="myReviewsCount()"
  />
  <app-dashboard [statuses]="claimStatuses()" [overdueCount]="overdueClaims().length" />
  <app-consolidated
    [ownMembers]="members()"
    [ownPeople]="summaryPeople()"
    dueTotal: this.dueBy().get(me.id) ?? 'n/a',
    overdueTotal: this.overdueTotalBy().get(me.id) ?? '0.00',
  };
});
// The role the signed-in user acts in on the sheet, as the store last told it; null until it answers.
private readonly myRole = signal<string | null>(null);
// The people the signed-in user added on this screen since the sheet was last loaded: a restricted user still
// sees them until the sheet is loaded again.
private readonly addedHere = signal<ReadonlySet<number>>(new Set());
private roleSheet: string | null = null;
// The people a restricted user may see on the list: their person, and everyone in the crews that person leads or
// belongs to; null when the list shows everyone. Every other figure is still over everyone on the sheet.
private readonly visibleIds = computed<ReadonlySet<number> | null>(() => {
  const role = this.myRole();
  if (role !== null && role !== 'restricted') return null;
  const me = this.me();
  if (role === null || me === undefined) return new Set(this.addedHere());
  const ids = new Set([...this.addedHere(), me.id]);
  for (const c of this.crewRoster.crews()) {
    if (c.leadId !== me.id && !c.members.some((m) => m.personId === me.id)) continue;
    if (c.leadId !== null) ids.add(c.leadId);
    for (const m of c.members) ids.add(m.personId);
  }
  return ids;
});
// The signed-in user's crew total: the due-totals of the crews their person leads, added up; blank when they lead
// none, or there is no such person.
protected readonly myCrewDueTotal = computed(() => {
  const me = this.me();
  if (me === undefined) return '';
  const led = this.crewRoster.crews().filter((c) => c.leadId === me.id);
  if (led.length === 0) return '';
  const due = this.dueBy();
  return sumSkippingNa(led.map((c) => crewDueTotal(c, due)));
});

constructor() {
  // The pools offer these people, and count a member retired, or held, as soon as they are.
  effect(() => {
    const list = this.people().map((p) => ({ id: p.id, name: p.name, retiredFrom: p.retiredFrom, holds: p.holds }));
    untracked(() => this.poolRoster.people.set(list));
  });
  // The crews offer these people, and add up their due-totals as the list shows them.
  effect(() => {
    const list = this.people().map((p) => ({ id: p.id, name: p.name, label: this.nameWithGrade(p) }));
    const due = this.dueBy();
    untracked(() => {
      this.crewRoster.people.set(list);
      this.crewRoster.dueBy.set(due);
    });
  });

